import { CetusTooltip, TableSortTh } from '@cetus/design'
import useDocumentSize from '@cetus/hooks/src/useDocumentSize'
import useWindowWidth from '@cetus/hooks/src/useWindowWidth'
import { useAccountStore } from '@cetus/stores'
import { Icon, NoData, SingleCoinImage, Table } from '@cetus/ui-kit'
import { Box, Center, HStack, Text } from '@chakra-ui/react'
import { useState } from 'react'
import { useNavigate } from 'react-router-dom'
import TypeCon from '../common/proModeAndChart/ProModeTradeTab/TypeCon'
import { poolsList } from './SelectPool'

type sortRule = 'desc' | 'asc'
export type type = {
  label: 'Date'
  value: 'date'
}
const tableStyle = {
  h: '100%',
  maxH: '400px',
  minH: '330px',
  borderRadius: '16px',
  border: '1px solid',
  borderColor: 'border',
  bg: 'bg_secondary'
}
function TransactionTableBlock({
  tableContainerWrapStyle = tableStyle,
  fixedHeader = true
}: {
  tableContainerWrapStyle?: any
  fixedHeader?: boolean
}) {
  const [type, setType] = useState('')
  const { currentAccount, onWalletModal } = useAccountStore()

  const { size } = useDocumentSize()
  const [sortRule, setSortRule] = useState<sortRule>('desc')
  const [sortBy, setSortBy] = useState<type>({ label: 'Date', value: 'date' })
  const navigate = useNavigate()
  const { isApp } = useWindowWidth()
  const clickSort = (item: type) => {
    if (isApp) {
      if (item?.value !== sortBy?.value) {
        setSortRule('desc')
        setSortBy(item)
      }
    } else {
      if (item?.value == sortBy?.value) {
        const rule = sortRule == 'desc' ? 'asc' : 'desc'
        setSortRule(rule)
      } else {
        setSortRule('desc')
        setSortBy(item)
      }
    }
  }
  const sortByList = [{ label: 'Date', value: 'date' }]
  const sortByObject = sortByList.reduce((obj: any, item) => {
    obj[item.value] = item
    return obj
  }, {})
  return (
    <Table
      dataSource={poolsList.filter((item: any) => (!type ? true : type.split(',').includes(item.side)))}
      columns={getColumns(type, setType, sortRule, sortBy, clickSort, sortByObject)}
      loading={false}
      fixedHeader={fixedHeader}
      headBg="bg_secondary"
      noData={
        !currentAccount?.address ? (
          <NoData type="nowallet" noBorder bg="none" onboard={() => onWalletModal(true)} />
        ) : poolsList?.length == 0 ? (
          <NoData type="nodata" text="No orders" noBorder bg="none" />
        ) : undefined
      }
      tableContainerWrapStyle={tableContainerWrapStyle}
    />
  )
}

const getColumns = (
  type: string,
  setType: (val: string) => void,
  sortRule: string,
  sortBy: type,
  clickSort: (value: type) => void,
  sortByObject: any
) => {
  return [
    {
      title: (
        <Box sx={{ '>div': { justifyContent: 'flex-start' } }}>
          <TableSortTh
            labelFontSize="13px"
            labelInfo={sortByObject['date']}
            sortRule={sortRule}
            sortBy={sortBy}
            clickSort={(value: type) => clickSort(value)}
          />
        </Box>
      ),
      key: 'date',
      thConfig: {
        w: '30%'
      },
      render: (item: any, index: number) => (
        <Text color="text_caption" fontSize="13px">
          16 Jul 2025 14:07
        </Text>
      )
    },
    {
      title: (
        <HStack justifyContent="flex-end" pt="8px" height="24px">
          <TypeCon
            type={type}
            setType={setType}
            filterList={['Open Position', 'Close Position', 'Decrease Size', 'Liquidation', 'Increase Leverage']}
            labelText="Side"
          />
        </HStack>
      ),
      key: 'type',
      thConfig: {
        w: '18%'
      },
      render: (item: any) => {
        const colorMap: any = {
          'Open Position': { color: 'primary', bg: 'primary_opacity.10' },
          'Close Position': { color: 'primary', bg: 'primary_opacity.10' },
          'Decrease Size': { color: 'primary_green', bg: 'primary_green_opacity.10' },
          Liquidation: { color: 'primary_yellow', bg: 'primary_yellow_opacity.10' },
          'Increase Leverage': { color: 'primary_green', bg: 'primary_green_opacity.10' }
        }
        const { color, bg } = colorMap['Open Position']
        return (
          <HStack w="100%" justifyContent="flex-end">
            <Text fontSize="12px" color={color} bg={bg} h="20px" p="0 8px" borderRadius="4px" lineHeight="20px">
              Open Position
            </Text>
          </HStack>
        )
      }
    },
    {
      title: (
        <Text color="primary_gray" fontSize="12px" textAlign="right" pt="8px">
          Tokens
        </Text>
      ),
      key: 'tokens',
      thConfig: {
        w: '18%'
      },
      render: (item: any) => (
        <HStack w="100%" justify="flex-end" gap="4px">
          <SingleCoinImage imageUrl="" boxSize="16px" imageStyle={{ w: '16px', h: '16px' }} />
          <Text textAlign="right" fontSize="13px" color="text_caption">
            123.4
          </Text>
        </HStack>
      )
    },
    {
      title: (
        <Text color="primary_gray" fontSize="12px" textAlign="right" pt="8px">
          Value
        </Text>
      ),
      key: 'value',
      thConfig: {
        w: '18%'
      },
      render: (item: any) => (
        <HStack w="100%" justify="flex-end" gap="0px">
          <Text color="text_caption" fontSize="13px">
            $9.99
          </Text>
        </HStack>
      )
    },
    {
      title: (
        <Text color="primary_gray" fontSize="12px" textAlign="right" pt="8px">
          Position Size
        </Text>
      ),
      key: 'size',
      thConfig: {
        w: '18%'
      },
      render: (item: any) => (
        <HStack w="100%" justify="flex-end" gap="0px">
          <Text color="text_caption" fontSize="13px">
            $9.99
          </Text>
        </HStack>
      )
    },
    {
      title: (
        <Text color="primary_gray" fontSize="12px" pt="8px">
          Txn
        </Text>
      ),
      key: 'txn',
      thConfig: {
        w: '18%'
      },
      render: (item: any) => (
        <CetusTooltip placement="top" tooltip={<Text fontSize="12px">View on Explorer</Text>}>
          <Center>
            <Icon xlinkHref="#icon-icon_link1" onClick={() => {}} />
          </Center>
        </CetusTooltip>
      )
    }
  ]
}

export default TransactionTableBlock
