import useLeverageStore from '@/store/leverage'
import { useDebounceFunction } from '@cetus/hooks'
import { CoinPairImage, Icon, SearchInput, Table } from '@cetus/ui-kit'
import { textEllipses } from '@cetus/utils'
import { Box, Button, HStack, Menu, MenuButton, MenuItem, MenuList, Portal, Skeleton, Text, VStack, useDisclosure } from '@chakra-ui/react'
import { useState } from 'react'

function SelectPool() {
  const { currentLeveragePool, setCurrentLeveragePool } = useLeverageStore()
  const menuDisclosure = useDisclosure()
  const [isHover, setIsHover] = useState(false)

  const [inputValue, setInputValue] = useState('')
  const [isLoading, setIsLoading] = useState(true)

  const handleInputChange = (value: string) => {
    const regValue = value.replace(/[^[a-zA-Z0-9\s]+$/g, '')
    setInputValue(regValue)
    if (regValue) {
      setIsLoading(true)
      debouncedFilter(regValue)
    }
  }
  const debouncedFilter = useDebounceFunction(async (value: string) => {
    console.log('🚀 ~ SelectPool ~ value:', value)
    setIsLoading(false)
  }, 500)

  return (
    <HStack
      w={{ base: '100%', lg: 'unset' }}
      position="relative"
      zIndex="100"
      cursor="pointer"
      onMouseEnter={() => setIsHover(true)}
      onMouseLeave={() => setIsHover(false)}
    >
      <Menu isOpen={menuDisclosure.isOpen} onClose={menuDisclosure.onClose}>
        <MenuButton
          as={Button}
          bg="none"
          _hover={{ bg: 'none' }}
          _active={{ bg: 'none' }}
          p="0"
          onClick={menuDisclosure.onOpen}
          w={{ base: '100%', lg: 'auto' }}
          h="32px"
        >
          <HStack>
            <CoinPairImage
              coinACoinType={currentLeveragePool?.displayTokenA?.coin_type}
              coinBCoinType={currentLeveragePool?.displayTokenB?.coin_type}
              coinAIconUrl={currentLeveragePool?.displayTokenA?.logo_url}
              coinBIconUrl={currentLeveragePool?.displayTokenB?.logo_url}
            />
            <Text fontSize="16px" color="text_caption" fontWeight="500">
              {`${textEllipses(currentLeveragePool?.displayTokenA?.symbol || '', 12) || ''}/${textEllipses(currentLeveragePool?.displayTokenB?.symbol || '', 12) || ''}`}
            </Text>
            <Icon
              fontSize="12px"
              xlinkHref="#icon-icon_arrow"
              transition="transform 0.5s"
              transform={menuDisclosure.isOpen ? 'rotate(180deg)' : 'rotate(0deg)'}
              svgFill={isHover ? 'text_caption' : 'text_paragraph'}
            />
          </HStack>
        </MenuButton>
        <Portal>
          <MenuList w={{ base: 'calc(100vw - 24px)', lg: '350px' }} borderRadius="12px" p="0px" mt="0" zIndex="999999">
            <Box
              w="100%"
              p="8px 8px 0"
              sx={{
                input: {
                  borderRadius: '8px',
                  fontSize: '14px'
                }
              }}
            >
              <SearchInput placeholder="Search tokens" searchText={inputValue} onChange={(value: string) => handleInputChange(value)} />
            </Box>
            <MenuItem closeOnSelect={false} p="0" w="100%">
              <Box w="100%" maxH="300px" overflowY="auto" p="4px 0px" sx={{ scrollbarGutter: 'stable both-edges' }}>
                <Table
                  columns={getColumns()}
                  dataSource={poolsList}
                  skeletonLength={3}
                  loading={false}
                  trPadding="8px"
                  onRowClick={(item: any) => {
                    setCurrentLeveragePool(item)
                    menuDisclosure.onClose()
                  }}
                  rowStyle={{
                    h: '40px',
                    cursor: 'pointer',
                    _hover: { bg: 'primary_opacity.10)' }
                  }}
                />
              </Box>
            </MenuItem>
          </MenuList>
        </Portal>
      </Menu>
    </HStack>
  )
}

