import useLeverageStore from '@/store/leverage'
import { SelectTab, TradeInput } from '@cetus/design'
import { useGetTokenBalance } from '@cetus/hooks/src/useTokenBalance'
import useTokenPrice from '@cetus/hooks/src/useTokenPrice'
import { textEllipses } from '@cetus/utils'
import { Button, VStack } from '@chakra-ui/react'
import { useCallback, useMemo, useState } from 'react'
import FlashBorrowFee from '../common/FlashBorrowFee'
import PriceDifference from '../common/PriceDifference'

export default function ClosePositionCon() {
  const isLong = true
  const { currentLeveragePool } = useLeverageStore()
  const [currentTab, setCurrentTab] = useState(`Close to ${currentLeveragePool?.displayTokenA?.symbol}`)
  const [currentTabToken, setCurrentTabToken] = useState(currentLeveragePool?.displayTokenA)
  const [inputValue, setInputValue] = useState<string>('')
  const { getTokenAmountValue } = useTokenPrice()
  const amountValue = getTokenAmountValue(currentTabToken?.coin_type, inputValue)
  const handleInputChange = useCallback((value: string) => {
    setInputValue(value)
  }, [])
  const tabList = useMemo(() => {
    return [
      {
        label: `Close to ${textEllipses(currentLeveragePool?.displayTokenA?.symbol, 8)}`,
        value: currentLeveragePool?.displayTokenA
      },
      {
        label: `Close to ${textEllipses(currentLeveragePool?.displayTokenB?.symbol, 8)}`,
        value: currentLeveragePool?.displayTokenB
      }
    ]
  }, [currentLeveragePool])

  const { balanceInfo } = useGetTokenBalance(currentTabToken)
  return (
    <VStack gap="12px" width="100%" justifyContent="space-between">
      <SelectTab
        type="outlineTab"
        wrapStyle={{
          w: '100%',
          h: '42px',
          bg: 'swap_bg_secondary',
          padding: '4px'
        }}
        itemStyle={{
          w: `50%`,
          fontSize: '14px',
          borderRadius: '8px'
        }}
        tabList={tabList}
        currentTab={currentTab}
        handleChangeTab={item => {
          setCurrentTab(item.label)
          setCurrentTabToken(item?.value)
        }}
      />
      <TradeInput
        title="Estimated Received"
        wrapStyle={{ h: 'unset' }}
        placeholder="0.0"
        value={inputValue}
        amountValue={amountValue}
        onChange={handleInputChange}
        balance={balanceInfo?.balanceFormat || ''}
        token={currentTabToken}
        // balanceLabel='Available'
        inputStyle={{ width: '100%' }}
        half={false}
        max={false}
      />
      <Button w="100%" h="48px" fontSize="18px" fontWeight="500" isDisabled={!inputValue}>
        Close Position
      </Button>
      <VStack w="100%" gap="16px" align="flex-start">
        <PriceDifference
          swapInToken={isLong ? currentLeveragePool?.displayTokenA : currentLeveragePool?.displayTokenB}
          outputToken={currentTabToken}
        />
        <FlashBorrowFee />
      </VStack>
    </VStack>
  )
}
