import ChartDataBlock from '@/components/leverage/ChartDataBlock'
import MarginTrading from '@/components/leverage/MarginTrading'
import PositionBlock from '@/components/leverage/PositionBlock'
import { poolsList } from '@/components/leverage/SelectPool'
import TransactionTableBlock from '@/components/leverage/TransactionTableBlock'
import useLeverageStore from '@/store/leverage'
import { SelectTab } from '@cetus/design'
import { CheckBox } from '@cetus/ui-kit'
import { HStack, Text, VStack } from '@chakra-ui/react'
import { useEffect, useState } from 'react'

function Leverage() {
  const [currentTab, setCurrentTab] = useState<'Positions' | 'Transactions'>('Positions')
  const [isChecked, setIsChecked] = useState(false)
  const { setCurrentLeveragePool } = useLeverageStore()
  useEffect(() => {
    setCurrentLeveragePool(poolsList[0])
  }, [poolsList])

  return (
    <HStack w="100%" gap="20px" mt="32px" align="flex-start">
      <VStack w="672px" align="flex-start" gap="16px">
        <ChartDataBlock />
        <HStack w="100%" justify="space-between" mb="-4px">
          <PositionAndTransTab currentTab={currentTab} setCurrentTab={setCurrentTab} />
          <HStack borderRadius="8px" justifyContent="center" alignItems="center">
            <CheckBox checked={isChecked} onClick={() => setIsChecked(!isChecked)} />
            <Text fontSize="12px" color={isChecked ? 'text_caption' : 'primary_gray'}>
              All Markets
            </Text>
          </HStack>
        </HStack>
        {currentTab == 'Positions' ? <PositionBlock /> : <TransactionTableBlock />}
      </VStack>
      <VStack w="468px">
        <MarginTrading />
      </VStack>
    </HStack>
  )
}
const tabList = [
  {
    label: 'Positions'
  },
  {
    label: 'Transactions'
  }
]
const PositionAndTransTab = ({
  currentTab,
  setCurrentTab
}: {
  currentTab: 'Positions' | 'Transactions'
  setCurrentTab: (tab: 'Positions' | 'Transactions') => void
}) => {
  return (
    <SelectTab
      type="borderTab"
      wrapStyle={{
        border: 'none',
        bg: 'none',
        w: {
          base: '100%',
          lg: 'unset'
        },
        h: '48px'
      }}
      itemStyle={{
        w: '50%',
        fontSize: '16px',
        mr: '32px'
      }}
      tabList={tabList}
      currentTab={currentTab}
      handleChangeTab={(item: any) => {
        setCurrentTab(item.label)
      }}
    />
  )
}
export default Leverage
