import Slippage from '@/components/common/Slippage'
import useLeverageStore from '@/store/leverage'
import { useGetTokenBalance } from '@cetus/hooks/src/useTokenBalance'
import { RefreshButton } from '@cetus/ui-kit'
import { isAvailableObject } from '@cetus/utils'
import { fixCoinType } from '@cetusprotocol/common-sdk'
import { Heading, HStack, Modal, ModalBody, ModalCloseButton, ModalContent, ModalHeader, ModalOverlay, Text, VStack } from '@chakra-ui/react'
import { useMemo, useState } from 'react'
import CurrentCoinPair from '../common/CurrentCoinPair'
import ClosePositionCon from './ClosePositionCon'
import ManageLeverageCon from './ManageLeverageCon'
import ManageList from './ManageList'
import ManageSizeCon from './ManageSizeCon'
import RepayDebtCon from './RepayDebtCon'
import TopUpCollateralCon from './TopUpCollateralCon'

type ManageProps = {
  isOpen: boolean
  onClose: () => void
}
const ManageLabelList = ['Manage Size', 'Manage Leverage', 'Repay Debt', 'Top Up Collateral', 'Close Position']

export default function ManagePositionModal({ isOpen, onClose }: ManageProps) {
  const [currentManage, setCurrentManage] = useState('Manage Size')
  const { currentLeveragePool } = useLeverageStore()
  const [currentToken, setCurrentToken] = useState(currentLeveragePool?.displayTokenA)
  const dropSelectTokenList: any = useMemo(() => {
    if (isAvailableObject(currentLeveragePool) && currentToken) {
      if (fixCoinType(currentLeveragePool?.displayTokenA?.coin_type) == fixCoinType(currentToken?.coin_type)) {
        return [{ ...currentLeveragePool?.displayTokenB }]
      } else {
        return [{ ...currentLeveragePool?.displayTokenA }]
      }
    }
  }, [currentLeveragePool, currentToken])
  const { balanceInfo } = useGetTokenBalance(currentToken)
  return (
    <Modal autoFocus={false} closeOnOverlayClick={false} returnFocusOnClose={false} isOpen={isOpen} onClose={onClose} isCentered>
      <ModalOverlay />
      <ModalContent>
        {/* 标题 */}
        <ModalHeader>
          <Heading fontWeight="500" fontSize="16px">
            Manage Position
          </Heading>
        </ModalHeader>
        <ModalCloseButton />
        <ModalBody p={{ base: '0px 12px 16px !important', lg: '0px 16px 20px !important' }}>
          <VStack gap="16px" w="100%" align="flex-start" userSelect="none" p="0px">
            <VStack gap="16px" w="100%" align="flex-start" bg="#192128" borderRadius="16px" p="16px">
              <CurrentCoinPair />
              <HStack w="100%" justify="space-between">
                <Text color="primary_gray">Size</Text>
                <Text color="text_caption">$100,000.99</Text>
              </HStack>
              <HStack w="100%" justify="space-between">
                <Text color="primary_gray">Entry Price</Text>
                <Text color="text_caption">$3.99</Text>
              </HStack>
              <HStack w="100%" justify="space-between">
                <Text color="primary_gray">PnL</Text>
                <Text color="primary_green">+$10.22 (+1.23%)</Text>
              </HStack>
            </VStack>

            <HStack w="100%" justify="space-between">
              <ManageList list={ManageLabelList} currentManage={currentManage} changeCurrentManage={(val: string) => setCurrentManage(val)} />
              <HStack>
                <Slippage />
                <RefreshButton handleRefresh={() => {}} w="28px" h="28px" innerStyle={{ bg: 'none' }} />
              </HStack>
            </HStack>
            {currentManage == 'Manage Size' && (
              <ManageSizeCon
                currentToken={currentToken}
                balanceInfo={balanceInfo}
                dropSelectTokenList={dropSelectTokenList}
                changeCurrentToken={value => {
                  setCurrentToken(value)
                }}
              />
            )}
            {currentManage == 'Manage Leverage' && <ManageLeverageCon />}
            {currentManage == 'Repay Debt' && (
              <RepayDebtCon
                currentToken={currentToken}
                balanceInfo={balanceInfo}
                dropSelectTokenList={dropSelectTokenList}
                changeCurrentToken={value => {
                  setCurrentToken(value)
                }}
              />
            )}
            {currentManage == 'Top Up Collateral' && (
              <TopUpCollateralCon
                currentToken={currentToken}
                balanceInfo={balanceInfo}
                dropSelectTokenList={dropSelectTokenList}
                changeCurrentToken={value => {
                  setCurrentToken(value)
                }}
              />
            )}
            {currentManage == 'Close Position' && <ClosePositionCon />}
          </VStack>
        </ModalBody>
      </ModalContent>
    </Modal>
  )
}
