import useLeverageTrading from '@/hooks/leverage/useLeverageTrading'
import useLeverageStore from '@/store/leverage'
import { SelectTab, TradeInputGroup } from '@cetus/design'
import { useAccountStore } from '@cetus/stores'
import { RefreshButton } from '@cetus/ui-kit'
import { isAvailableObject } from '@cetus/utils'
import { fixCoinType } from '@cetusprotocol/common-sdk'
import { Button, HStack, Image, Text, VStack } from '@chakra-ui/react'
import { useMemo, useState } from 'react'
import Slippage from '../common/Slippage'
import TradingShowData from './TrandingShowData'
import LeverageSlider from './common/LeverageSlider'

function MarginTrading() {
  const [currentTab, setCurrentTab] = useState<'Buy / Long' | 'Sell / Short'>('Buy / Long')
  const { depositToken, sizeToken, leverageValue, currentLeveragePool } = useLeverageStore()
  const { currentAccount, onWalletModal } = useAccountStore()
  const {
    depositTokenAmount,
    sizeTokenAmount,
    depositTokenBalanceInfo,
    sizeTokenBalanceInfo,
    depositTokenAmountValue,
    sizeTokenAmountValue,
    handleSelectToken,
    btnStatusText,
    handleAmountChange,
    sliderStep,
    changeLeverageValue,
    toOpen
  } = useLeverageTrading()

  const handleRefresh = () => {}

  const dropSelectTokenList = useMemo(() => {
    if (isAvailableObject(currentLeveragePool) && depositToken) {
      if (fixCoinType(currentLeveragePool?.displayTokenA?.coin_type) == fixCoinType(depositToken?.coin_type)) {
        return [{ ...currentLeveragePool?.displayTokenB }]
      } else {
        return [{ ...currentLeveragePool?.displayTokenA }]
      }
    }
  }, [currentLeveragePool, depositToken])

  return (
    <VStack w="100%" align="flex-start">
      <HStack mb="8px" position="relative" gap="0" w="100%" justify="space-between">
        <Text lineHeight="32px" color="text_caption" fontSize="16px">
          Margin Trading
        </Text>
        <Image src="/images/icon_beta@2x.png" position="absolute" left="114px" top="-2px" h="12px" />
        <HStack>
          <Slippage />
          <RefreshButton handleRefresh={handleRefresh} w="28px" h="28px" innerStyle={{ bg: 'none' }} />
        </HStack>
      </HStack>
      <MarginTradingTab currentTab={currentTab} setCurrentTab={setCurrentTab} />
      <TradeInputGroup
        from={{
          title: 'You Deposit',
          selectable: true,
          balance: depositTokenBalanceInfo?.balanceFormat || '',
          value: depositTokenAmount,
          amountValue: depositTokenAmountValue,
          loading: false,
          onChange: value => {
            handleAmountChange(value)
          },
          placeholder: '0.0',
          token: depositToken,
          dropSelectTokenList: dropSelectTokenList,
          changeCurrentToken: value => {
            handleSelectToken(value)
          }
        }}
        to={{
          title: 'Long Size',
          inputAllowed: false,
          balance: sizeTokenBalanceInfo?.balanceFormat || '',
          value: sizeTokenAmount,
          amountValue: sizeTokenAmountValue,
          loading: false,
          onChange: value => {
            handleAmountChange(value)
          },
          isShowBalance: false,
          half: false,
          max: false,
          placeholder: '0.0',
          token: sizeToken
        }}
        iconHover={false}
        iconParams={{
          xlinkHref: '#icon-arrow_down',
          svgFill: 'text_caption'
        }}
      />
      <LeverageSlider leverageValue={leverageValue} sliderStep={sliderStep} changeLeverageValue={changeLeverageValue} />
      <Button
        onClick={() => {
          if (currentAccount) {
            toOpen()
          } else {
            onWalletModal(true)
          }
        }}
        isLoading={false}
        isDisabled={btnStatusText?.disabled}
        w="100%"
        h="52px"
        fontSize="18px"
        fontWeight="500"
      >
        {btnStatusText?.text}
      </Button>
      {depositTokenAmount && <TradingShowData isLong={currentTab == 'Buy / Long'} />}
    </VStack>
  )
}
const MarginTradingTabList = [
  {
    label: 'Buy / Long'
  },
  {
    label: 'Sell / Short'
  }
]
const MarginTradingTab = ({
  currentTab,
  setCurrentTab
}: {
  currentTab: 'Buy / Long' | 'Sell / Short'
  setCurrentTab: (tab: 'Buy / Long' | 'Sell / Short') => void
}) => {
  return (
    <SelectTab<any, any>
      type="outlineTab"
      tabList={MarginTradingTabList}
      currentTab={currentTab}
      handleChangeTab={tab => setCurrentTab(tab?.label)}
      wrapStyle={{
        w: '100%',
        h: '48px',
        p: '4px',
        border: '1px solid',
        borderColor: 'border',
        borderRadius: '16px',
        gap: '4px',
        zIndex: '99'
      }}
      itemStyle={{
        w: '50%',
        h: '100%',
        p: '4px 8px',
        borderRadius: '12px',
        gap: '4px',
        justifyContent: 'center',
        alignItems: 'center',
        fontSize: '14px',
        fontWeight: '500',
        // 使用 Chakra UI 的 sx 支持条件样式
        sx: {
          '&[data-active="true"]': {
            backgroundColor: currentTab == 'Buy / Long' ? 'primary_green_opacity.10' : 'primary_red_opacity.10',
            color: currentTab == 'Buy / Long' ? 'primary_green' : 'primary_red'
          }
        }
      }}
      selectTabItemTextStyle={{
        color: 'primary_gray',
        sx: {
          '&[data-active="true"]': {
            color: currentTab == 'Buy / Long' ? 'primary_green' : 'primary_red'
          }
        }
      }}
    />
  )
}

export default MarginTrading
