import useLeverageStore from '@/store/leverage'
import { CurrentPrice } from '@cetus/design'
import { Token } from '@cetus/types'
import { Icon } from '@cetus/ui-kit'
import { textEllipses } from '@cetus/utils'
import { HStack, Text, VStack } from '@chakra-ui/react'
import { useState } from 'react'

function PriceDifference({ swapInToken, outputToken }: { swapInToken: Token | undefined; outputToken: Token | undefined }) {
  const [isShowPriceDrop, setIsShowPriceDrop] = useState(false)
  const { currentLeveragePool } = useLeverageStore()
  return (
    <>
      <HStack w="100%" justify="space-between">
        <Text color="primary_gray">Price Difference</Text>
        <HStack cursor="pointer" gap="4px" onClick={() => setIsShowPriceDrop(!isShowPriceDrop)}>
          <Text color="primary_green">0.46%</Text>
          <Icon
            fontSize="12px"
            xlinkHref="#icon-icon_arrow"
            transition="transform 0.5s"
            transform={isShowPriceDrop ? 'rotate(180deg)' : 'rotate(0deg)'}
          />
        </HStack>
      </HStack>
      {isShowPriceDrop && (
        <VStack w="100%" p="12px" bg="card_bg" borderRadius="8px" gap="12px">
          <HStack w="100%" justify="space-between">
            <Text color="primary_gray">Swap In</Text>
            <Text color="text_caption">0.1890 {textEllipses(swapInToken?.symbol, 10)}</Text>
          </HStack>
          <HStack w="100%" justify="space-between">
            <Text color="primary_gray">Min. Output</Text>
            <Text color="text_caption">0.179 {textEllipses(outputToken?.symbol, 10)}</Text>
          </HStack>
          <HStack w="100%" justify="space-between">
            <Text color="primary_gray">Swap Rate</Text>
            <CurrentPrice
              color="text_caption"
              fromValue="1"
              toValue="3.8"
              noIcon
              fromToken={currentLeveragePool?.displayTokenA}
              toToken={currentLeveragePool?.displayTokenB}
            />
          </HStack>
        </VStack>
      )}
    </>
  )
}

export default PriceDifference
