import { Block } from '@cetus/design'
import { Icon } from '@cetus/ui-kit'
import { d } from '@cetus/utils'
import { Button, HStack, Slider, SliderFilledTrack, SliderThumb, SliderTrack, Text, Tooltip } from '@chakra-ui/react'

function LeverageSlider({
  leverageValue,
  sliderStep,
  changeLeverageValue
}: {
  leverageValue: number
  sliderStep: any
  changeLeverageValue: (val: any) => void
}) {
  return (
    <Block p="16px" borderRadius="16px">
      <Text color="primary_gray">Leverage (1.1x - 3.5x)</Text>
      <HStack mt="20px" w="100%">
        <HStack mr="32px">
          <Button
            bg="primary_opacity.10"
            p="0px"
            w="20px"
            h="20px"
            borderRadius="4px !important"
            variant="ghost"
            border="none"
            isDisabled={d(leverageValue).gte(3.5)}
            _hover={{ bg: 'primary_opacity.10', border: 'none' }}
            _active={{ bg: 'primary_opacity.10', border: 'none' }}
            onClick={() => changeLeverageValue(d(leverageValue).plus(sliderStep).toNumber())}
          >
            <Icon svgFill="primary" svgHover="primary" xlinkHref={'#icon-a-icon_add1'} fontSize="14px" />
          </Button>
          <Text w="36px" textAlign="center" fontSize="18px" color="text_caption" fontWeight="500" whiteSpace="nowrap">
            {leverageValue}x
          </Text>
          <Button
            bg="primary_opacity.10"
            p="0px"
            w="20px"
            h="20px"
            borderRadius="4px !important"
            variant="ghost"
            border="none"
            _hover={{ bg: 'primary_opacity.10', border: 'none' }}
            _active={{ bg: 'primary_opacity.10', border: 'none' }}
            isDisabled={d(leverageValue).lte(1.1)}
            onClick={() => changeLeverageValue(d(leverageValue).minus(sliderStep).toNumber())}
          >
            <Icon svgFill="primary" svgHover="primary" xlinkHref={'#icon-tx_remove'} fontSize="14px" />
          </Button>
        </HStack>
        <Slider
          aria-label="slider-ex-1"
          min={1.1}
          max={3.5}
          step={sliderStep}
          focusThumbOnChange={false}
          value={leverageValue}
          onChange={value => changeLeverageValue(value)}
        >
          <SliderTrack bg="bg_four" h="4px">
            <SliderFilledTrack h="4px" />
          </SliderTrack>
          <Tooltip
            p="4px"
            borderRadius="4px"
            borderColor="border"
            bg="primary_opacity.10"
            color="primary"
            placement="top"
            fontSize="12px"
            label={`${leverageValue}x`}
          >
            <SliderThumb />
          </Tooltip>
        </Slider>
      </HStack>
    </Block>
  )
}

export default LeverageSlider
