import { Token } from '@cetus/types/src/common-types'
import { StateCreator, create } from 'zustand'

interface LeverageState {
  // 保证金coin
  depositToken?: Token | undefined
  // size coin
  sizeToken?: Token | undefined
  setDepositToken: (coin: Token | undefined) => void
  setSizeToken: (coin: Token | undefined) => void
  currentLeveragePool: any
  setCurrentLeveragePool: (pool: any) => void
  leverageValue: number
  setLeverageValue: (value: number) => void
}

const store: StateCreator<LeverageState> = (set, get) => ({
  depositToken: undefined,
  sizeToken: undefined,
  setDepositToken: (coin: Token | undefined) => {
    set(() => ({
      depositToken: coin
    }))
  },
  setSizeToken: (coin: Token | undefined) => {
    set(() => ({
      sizeToken: coin
    }))
  },
  currentLeveragePool: undefined,
  setCurrentLeveragePool: (pool: any) => {
    set(() => ({
      currentLeveragePool: pool,
      depositToken: pool?.displayTokenA as any,
      sizeToken: pool?.displayTokenA as any
    }))
  },
  leverageValue: 1.1,
  setLeverageValue: (value: number) => {
    set(() => ({
      leverageValue: value
    }))
  }
})

const useLeverageStore = create(store)
export default useLeverageStore
