import useLeverageStore from '@/store/leverage'
import { CoinPairImage } from '@cetus/ui-kit'
import { textEllipses } from '@cetus/utils'
import { HStack, Text, VStack } from '@chakra-ui/react'

function CurrentCoinPair({ symbolEllipsesDecimals = 8 }: { symbolEllipsesDecimals?: number }) {
  const { currentLeveragePool } = useLeverageStore()
  return (
    <HStack w="100%" gap="4px">
      <CoinPairImage
        coinACoinType={currentLeveragePool?.displayTokenA?.coin_type}
        coinBCoinType={currentLeveragePool?.displayTokenB?.coin_type}
        coinAIconUrl={currentLeveragePool?.displayTokenA?.logo_url}
        coinBIconUrl={currentLeveragePool?.displayTokenB?.logo_url}
        imgBoxStyle={{ w: '28px', h: '28px' }}
      />
      <VStack gap="4px" align="flex-start">
        <Text color="text_caption">
          {textEllipses(currentLeveragePool?.displayTokenA?.symbol || '', symbolEllipsesDecimals)}/
          {textEllipses(currentLeveragePool?.displayTokenB?.symbol || '', symbolEllipsesDecimals)}
        </Text>
        <Text h="16px" lineHeight="16px" p="0 4px" bg="primary_green_opacity.10" color="primary_green" fontSize="12px" borderRadius="4px">
          2.0x Long
        </Text>
      </VStack>
    </HStack>
  )
}

export default CurrentCoinPair
