import useLeverageStore from '@/store/leverage'
import { Block, CetusTooltip } from '@cetus/design'
import { Icon } from '@cetus/ui-kit'
import { textEllipses } from '@cetus/utils'
import { fixCoinType } from '@cetusprotocol/common-sdk'
import { HStack, Text, VStack } from '@chakra-ui/react'
import { useEffect, useState } from 'react'
import { LimitPriceChart } from '../limit/LimitPriceChart'
import SelectPool from './SelectPool'

function ChartDataBlock() {
  const { currentLeveragePool } = useLeverageStore()
  const [supplyAprToken, setSupplyAprToken] = useState(currentLeveragePool?.displayTokenA)
  const [borrowAprToken, setBorrowAprToken] = useState(currentLeveragePool?.displayTokenA)

  const changeAprToken = (type: 'supply' | 'borrow') => {
    const currentToken = type === 'supply' ? supplyAprToken : borrowAprToken
    const setToken = type === 'supply' ? setSupplyAprToken : setBorrowAprToken

    const token =
      fixCoinType(currentToken?.coin_type) === fixCoinType(currentLeveragePool?.displayTokenA?.coin_type)
        ? currentLeveragePool?.displayTokenB
        : currentLeveragePool?.displayTokenA

    setToken(token)
  }

  useEffect(() => {
    setSupplyAprToken(currentLeveragePool?.displayTokenA)
    setBorrowAprToken(currentLeveragePool?.displayTokenA)
  }, [currentLeveragePool])

  return (
    <VStack w="100%">
      <HStack mb="8px" w="100%" justify="space-between">
        <SelectPool />
        <HStack>
          <Text fontSize="20px" fontWeight="500" color="text_caption">
            {currentLeveragePool?.price}
          </Text>
          <HStack
            gap="2px"
            justify="flex-end"
            h="20px"
            borderRadius="12px"
            p="0 8px"
            bg={currentLeveragePool?.priceChange?.includes('-') ? 'primary_red_opacity.10' : 'primary_green_opacity.10'}
          >
            {currentLeveragePool?.priceChange !== '0%' && (
              <Icon
                fontSize="12px"
                xlinkHref="#icon-icon_arrow"
                transition="transform 0.5s"
                transform={currentLeveragePool?.priceChange?.includes('-') ? 'rotate(0deg)' : 'rotate(180deg)'}
                svgFill={currentLeveragePool?.priceChange?.includes('-') ? 'primary_red' : 'primary_green'}
              />
            )}
            <Text
              color={
                currentLeveragePool?.priceChange?.includes('-')
                  ? 'primary_red'
                  : currentLeveragePool?.priceChange === '0%'
                    ? 'text_caption'
                    : 'primary_green'
              }
            >
              {currentLeveragePool?.priceChange?.includes('-')
                ? currentLeveragePool?.priceChange?.split('-')[1]
                : currentLeveragePool?.priceChange?.split('+')[1]}
            </Text>
          </HStack>
        </HStack>
      </HStack>
      <Block mb="-40px" borderRadius="16px" p="16px" pb="48px">
        <HStack w="100%" justify="space-between" sx={{ '>div': { minW: '22%' } }}>
          <VStack align="flex-start">
            <Text fontSize="12px">Long Liquidity</Text>
            <Text color="text_caption">$14,804,557.5</Text>
          </VStack>
          <VStack align="flex-start">
            <Text fontSize="12px">Short Liquidity</Text>
            <Text color="text_caption">$14,804,557.5</Text>
          </VStack>
          <VStack align="flex-start">
            <HStack gap="4px">
              <Text fontSize="12px">{textEllipses(supplyAprToken?.symbol || '', 8)} Supply APR</Text>
              <Icon xlinkHref="#icon-icon_swap1" w="14px" h="14px" svgW="14px" svgH="14px" onClick={() => changeAprToken('supply')} />
            </HStack>
            <CetusTooltip placement="top" tooltip={<Text fontSize="12px">APY data is sourced from Suilend's real-time lending market.</Text>}>
              <Text color="primary_green" borderBottom="1px dashed" borderColor="text_paragraph">
                4.75%
              </Text>
            </CetusTooltip>
          </VStack>
          <VStack align="flex-start">
            <HStack gap="4px">
              <Text fontSize="12px">{textEllipses(borrowAprToken?.symbol || '', 8)} Borrow APR</Text>
              <Icon xlinkHref="#icon-icon_swap1" w="14px" h="14px" svgW="14px" svgH="14px" onClick={() => changeAprToken('borrow')} />
            </HStack>
            <CetusTooltip placement="top" tooltip={<Text fontSize="12px">APY data is sourced from Suilend's real-time lending market.</Text>}>
              <Text color="primary_green" borderBottom="1px dashed" borderColor="text_paragraph">
                4.75%
              </Text>
            </CetusTooltip>
          </VStack>
        </HStack>
      </Block>
      <LimitPriceChart
        showPoolInfo={false}
        chartHeight="335px"
        baseToken={currentLeveragePool?.displayTokenA}
        quoteToken={currentLeveragePool?.displayTokenB}
      />
    </VStack>
  )
}

export default ChartDataBlock
