import useWindowWidth from '@cetus/hooks/src/useWindowWidth'
import { Icon } from '@cetus/ui-kit'
import { Button, HStack, Menu, MenuButton, MenuList, Text, VStack } from '@chakra-ui/react'
import { useState } from 'react'

function ManageList({
  list,
  currentManage,
  changeCurrentManage,
  labelStyle
}: {
  list: string[]
  currentManage: string
  changeCurrentManage: (val: string) => void
  labelStyle?: any
}) {
  const { isApp } = useWindowWidth()
  const [isHover, setIsHover] = useState(false)

  return (
    <Menu isLazy>
      {({ isOpen, onClose }) => (
        <>
          <MenuButton
            as={Button}
            variant="outline"
            h="36px"
            border="none"
            bg="none"
            p="0"
            height="16px"
            lineHeight="16px"
            w={{ base: '100%', lg: 'unset' }}
            _hover={{ bg: 'none' }}
            _active={{ bg: 'none' }}
            onMouseEnter={() => setIsHover(true)}
            onMouseLeave={() => setIsHover(false)}
          >
            <HStack gap="0" justify="center">
              <Text color="text_caption" fontSize="16px" {...labelStyle}>
                {currentManage}
              </Text>
              <Icon
                transition="transform 0.5s"
                transform={isOpen ? 'rotate(180deg)' : 'rotate(0deg)'}
                mt="1px"
                xlinkHref="#icon-icon_arrow"
                svgW="14px"
                svgH="14px"
                svgFill={isHover ? 'text_caption' : 'text_paragraph'}
              />
            </HStack>
          </MenuButton>

          <MenuList
            zIndex={9999}
            p="4px"
            sx={{
              position: 'absolute',
              left: 0,
              top: '8px'
            }}
            minW="156px"
          >
            <VStack>
              {list.map(item => (
                <HStack key={item} h="30px" justify="space-between" w="100%" p="0 12px" onClick={() => changeCurrentManage(item)} cursor="pointer">
                  <Text>{item}</Text>
                </HStack>
              ))}
            </VStack>
          </MenuList>
        </>
      )}
    </Menu>
  )
}

export default ManageList
