import useLeverageStore from '@/store/leverage'
import { Block, SelectTab } from '@cetus/design'
import useWindowWidth from '@cetus/hooks/src/useWindowWidth'
import { CheckBox } from '@cetus/ui-kit'
import { formatNumber, formatTimestamp, textEllipses, timeFormatUTC } from '@cetus/utils'
import { HStack, Text, VStack } from '@chakra-ui/react'
import { useEffect, useMemo, useState } from 'react'
import { Line, LineChart, ResponsiveContainer, Tooltip, XAxis, YAxis } from 'recharts'
import { CustomizedNetValueRightYAxisTick } from '../chart/CustomizedAxisTick'

const chartTypeList = [
  {
    label: '24H'
  },
  {
    label: '7D'
  },
  {
    label: '30D'
  }
]

export default function PositionItemAnalytics() {
  const { currentLeveragePool } = useLeverageStore()
  const [dateType, setDateType] = useState<'24H' | '1W'>('24H')
  const [currentCoinType, setCurrentCoinType] = useState(currentLeveragePool?.displayTokenA?.coin_type)
  const { isApp } = useWindowWidth()
  const lines = [
    { key: 'netValue', color: '#6FBCF0', label: 'Net Value' },
    { key: 'totalCollateral', color: '#07EBAD', label: 'Total Collateral' },
    { key: 'debtValue', color: '#FFCA68', label: 'Debt Value' }
  ]
  const [visibleLines, setVisibleLines] = useState(lines.map(l => l.key))
  const handleChange = (values: string) => {
    setVisibleLines(prev => {
      if (prev.includes(values)) {
        return prev.filter(i => i !== values)
      } else {
        return [...prev, values]
      }
    })
  }

  useEffect(() => {
    setCurrentCoinType(currentLeveragePool?.displayTokenA?.coin_type)
  }, [currentLeveragePool])

  const tokenList = useMemo(() => {
    return [
      {
        label: textEllipses(currentLeveragePool?.displayTokenA?.symbol || '', 8),
        value: currentLeveragePool?.displayTokenA?.coin_type
      },
      {
        label: textEllipses(currentLeveragePool?.displayTokenB?.symbol || '', 8),
        value: currentLeveragePool?.displayTokenB?.coin_type
      }
    ]
  }, [currentLeveragePool])
  return (
    <Block border="none" padding="0" mt="8px">
      <HStack justify="space-between" mb="16px">
        <HStack pr="12px" w="100%" justify="space-between" gap="4px">
          <Text fontWeight="500" fontSize="14px" color="text_caption">
            Net Value
          </Text>
          <HStack w="calc(100% - 80px)" align="flex-end" justify="flex-end">
            <SelectTab
              type="outlineTab"
              tabList={tokenList}
              currentTab={currentCoinType}
              isActive={(currentTab, tab) => currentTab === tab.value}
              handleChangeTab={tab => setCurrentCoinType(tab.value)}
              wrapStyle={{
                h: '28px',
                p: '3px',
                borderRadius: '8px'
              }}
              itemStyle={{
                minW: '50px',
                p: '0 12px',
                flex: '1',
                fontSize: '12px'
              }}
            />
            <SelectTab
              type="outlineTab"
              tabList={chartTypeList}
              currentTab={dateType}
              handleChangeTab={tab => setDateType(tab.label)}
              wrapStyle={{
                w: '120px',
                h: '28px',
                p: '3px',
                borderRadius: '8px'
              }}
              itemStyle={{
                flex: '1',
                fontSize: '12px',
                margin: '0px'
              }}
            />
          </HStack>
        </HStack>
      </HStack>
      <ResponsiveContainer width="100%" height={300}>
        <LineChart data={data} margin={{ top: 0, left: 10, right: 0, bottom: 10 }}>
          <XAxis
            dataKey="time"
            fontSize="12px"
            axisLine={false}
            tickLine={false}
            tick={{ fill: '#909CA4' }}
            dy={16}
            interval={data?.length <= 8 ? 0 : undefined}
          />
          <YAxis
            yAxisId="right"
            orientation="right"
            fontSize="12px"
            axisLine={false}
            tickLine={false}
            tickFormatter={value => formatNumber(value, 4)}
            tick={<CustomizedNetValueRightYAxisTick />}
          />
          <Tooltip content={<PositionItemAnalyticsTooltip lines={lines} />} cursor={<CustomCursor />} />

          {lines.map(line =>
            visibleLines.includes(line.key) ? (
              <Line yAxisId="right" key={line.key} type="monotone" dataKey={line.key} stroke={line.color} dot={false} isAnimationActive={false} />
            ) : null
          )}
        </LineChart>
      </ResponsiveContainer>
      <HStack w="100%" justify="center" gap="24px" mt="16px">
        {lines?.map((line: any) => {
          return (
            <HStack key={line.key} onClick={() => handleChange(line?.key)}>
              <HStack sx={{ svg: { fill: `${line?.color} !important ` } }}>
                <CheckBox checked={visibleLines.includes(line.key)} onClick={() => {}} />
                <Text color={line?.color}>{line.label}</Text>
              </HStack>
            </HStack>
          )
        })}
      </HStack>
    </Block>
  )
}

