function PositionItemAnalyticsTooltip({ payload, label, lines }) {
  const linesObj = lines.reduce((acc, cur) => {
    acc[cur?.key] = cur
    return acc
  }, {})
  console.log('🚀 ~ PositionItemAnalyticsTooltip ~ lines:', linesObj, payload, label, lines)
  if (!payload || !payload.length) return null

  return (
    <VStack
      border="1px solid"
      borderColor="border"
      gap="12px"
      padding="12px"
      bg="bg_secondary"
      borderRadius="12px"
      alignItems="flex-start"
      spacing="6px"
    >
      <Text fontSize="12px" color="primary_gray">
        {formatTimestamp(payload[0]?.payload?.date * 1000)}
      </Text>
      {payload.map((item: any) => (
        <HStack w="100%" key={item.dataKey} justify="space-between">
          <Text fontSize="12px" color={item.color} fontWeight="500">
            {linesObj[item.name]?.label}
          </Text>
          <Text fontSize="12px" color={item.color} fontWeight="500">
            ${item.value}
          </Text>
        </HStack>
      ))}
    </VStack>
  )
}

const CustomCursor = props => {
  const { points, width, height } = props
  const { x } = points[0]

  return (
    <g>
      <defs>
        <linearGradient id="cursorGradient" x1="0%" y1="0%" x2="0%" y2="100%">
          <stop offset="0%" stopColor="rgba(104, 255, 216, 0)" />
          <stop offset="50%" stopColor="rgba(55, 255, 228, 1)" />
          <stop offset="100%" stopColor="rgba(104, 255, 216, 0)" />
        </linearGradient>
      </defs>
      <rect
        x={x - 1} // 宽度为2，所以向左偏移1
        y={0}
        width={2}
        height={height}
        fill="url(#cursorGradient)"
      />
    </g>
  )
}
