import useTransaction from '@/hooks/common/useTransaction'
import useGlobalStore from '@/store/common/global'
import useLeverageStore from '@/store/leverage'
import { useAccountBalance } from '@cetus/hooks'
import { useGetTokenBalance } from '@cetus/hooks/src/useTokenBalance'
import useTokenPrice from '@cetus/hooks/src/useTokenPrice'
import { useAccountStore } from '@cetus/stores'
import { Token } from '@cetus/types'
import { d, textEllipses } from '@cetus/utils'
import { useEffect, useMemo, useRef, useState } from 'react'
import useInsufficientBalanceToast from '../common/useInsufficientBalanceToast'

export const sliderStep = 0.1
export default function useLeverageTrading() {
  const { fetchAccountBalance } = useAccountBalance()
  const { currentAccount } = useAccountStore()
  useEffect(() => {
    if (currentAccount?.address) {
      fetchAccountBalance()
    }
  }, [])
  const { fetchTokenPrices, getTokenAmountValue, getTokenPrice } = useTokenPrice()
  const [depositTokenAmount, setDepositTokenAmount] = useState('')
  const [sizeTokenAmount, setSizeTokenAmount] = useState('')
  const { depositToken, sizeToken, setDepositToken, leverageValue, setLeverageValue, currentLeveragePool } = useLeverageStore()

  const depositTokenPrice = getTokenPrice(depositToken?.coin_type)
  const sizeTokenPrice = getTokenPrice(sizeToken?.coin_type)

  const changeLeverageValue = (value: number) => {
    setLeverageValue(value)
    if (+depositTokenAmount && depositTokenPrice?.price && sizeTokenPrice?.price) {
      setSizeTokenAmount(d(depositTokenAmount).mul(depositTokenPrice?.price).div(sizeTokenPrice.price).mul(value).toString())
    }
  }

  useEffect(() => {
    setDepositTokenAmount('')
    setSizeTokenAmount('')
    return () => {}
  }, [])

  useEffect(() => {
    getTokensPrice()
  }, [depositToken?.coin_type, sizeToken?.coin_type])

  const getTokensPrice = () => {
    const uniqueTokens: any =
      (depositToken?.coin_type || sizeToken?.coin_type) && Array.from(new Set([depositToken?.coin_type, sizeToken?.coin_type]))
    if (uniqueTokens && uniqueTokens?.length > 0) {
      fetchTokenPrices(uniqueTokens)
    }
  }
  // 余额
  const { balanceInfo: depositTokenBalanceInfo } = useGetTokenBalance(depositToken)
  const { balanceInfo: sizeTokenBalanceInfo } = useGetTokenBalance(sizeToken)

  // 价值
  const depositTokenAmountValue = getTokenAmountValue(depositToken?.coin_type, depositTokenAmount)
  const sizeTokenAmountValue = getTokenAmountValue(sizeToken?.coin_type, sizeTokenAmount)

  const [uuid, setUuid] = useState<string>('')
  const uuidRef = useRef<string>('')

  useEffect(() => {
    uuidRef.current = uuid
  }, [uuid])

  const resetInputAmount = () => {
    setDepositTokenAmount('')
    setSizeTokenAmount('')
    setUuid('')
  }

  const handleAmountChange = (value: string) => {
    console.log('🚀 ~ handleAmountChange ~ value:', depositTokenPrice, sizeTokenPrice, value)
    setDepositTokenAmount(value)
    if (+value) {
      if (depositTokenPrice?.price && sizeTokenPrice?.price) {
        setSizeTokenAmount(d(value).mul(depositTokenPrice?.price).div(sizeTokenPrice.price).mul(leverageValue).toString())
      }
    } else {
      setSizeTokenAmount('')
    }
  }

  const handleSelectToken = (token: Token) => {
    setDepositTokenAmount('')
    setSizeTokenAmount('')
    setDepositToken(token)
  }
  const btnStatusText = useMemo(() => {
    const btnInfo: {
      text?: string
      disabled: boolean
    } = {
      text: `Open ${textEllipses(depositToken?.symbol, 10)} Long`,
      disabled: false
    }
    if (!currentAccount?.address) {
      btnInfo.text = 'Connect Wallet'
      btnInfo.disabled = false
      return btnInfo
    }

    // 判断输入
    if (!+depositTokenAmount) {
      btnInfo.text = 'Enter an amount'
      btnInfo.disabled = true
      return btnInfo
    }

    // 前端写死最小$5
    if (+depositTokenAmount) {
      if (d(depositTokenAmountValue).lt(5)) {
        btnInfo.text = 'Deposit at least $5'
        btnInfo.disabled = true
      }
      if (d(depositTokenAmountValue).gt(100000)) {
        btnInfo.text = 'Opening amount cannot exceed $100,000.'
        btnInfo.disabled = true
      }
      return btnInfo
    }

    //判断余额
    if (depositTokenAmount && d(depositTokenAmount).gt(depositTokenBalanceInfo?.balanceFormat || 0)) {
      btnInfo.disabled = true
      btnInfo.text = `Insufficient ${textEllipses(depositToken?.symbol, 10)} Balance`
      return btnInfo
    }

    if (!+depositTokenAmount || !+sizeTokenAmount) {
      btnInfo.disabled = true
      return btnInfo
    }

    return btnInfo
  }, [depositTokenAmountValue, depositTokenAmount, sizeTokenAmount, depositTokenBalanceInfo, sizeTokenBalanceInfo, currentAccount?.address])

  const { signAndExecuteTransaction } = useTransaction()
  const { showInsufficientBalanceToast } = useInsufficientBalanceToast()
  const { mevProtect, maxCapForGas, transactionMode, customGasPrice, slippage, zapSlippage } = useGlobalStore()
  const toOpen = () => {}
  return {
    sliderStep,
    depositTokenAmount,
    sizeTokenAmount,
    depositTokenBalanceInfo,
    sizeTokenBalanceInfo,
    depositTokenAmountValue,
    sizeTokenAmountValue,
    resetInputAmount,
    handleAmountChange,
    changeLeverageValue,
    handleSelectToken,
    toOpen,
    btnStatusText
  }
}
