import { PositionSlider } from '@/components/position/details/RemoveBlock'
import { Block, TradeInput } from '@cetus/design'
import useTokenPrice from '@cetus/hooks/src/useTokenPrice'
import { Token } from '@cetus/types'
import { d } from '@cetus/utils'
import { Button, HStack, Text, VStack } from '@chakra-ui/react'
import { useCallback, useState } from 'react'
import Leverage from '../common/Leverage'
import LiquidationPrice from '../common/LiquidationPrice'

export default function RepayDebtCon({
  currentToken,
  balanceInfo,
  dropSelectTokenList,
  changeCurrentToken
}: {
  currentToken: Token
  balanceInfo: any
  dropSelectTokenList: Token[]
  changeCurrentToken: (token: Token) => void
}) {
  const [inputValue, setInputValue] = useState<string>('')
  const { getTokenAmountValue } = useTokenPrice()
  const amountValue = getTokenAmountValue(currentToken?.coin_type, inputValue)
  const handleInputChange = useCallback((value: string) => {
    setInputValue(value)
  }, [])

  const [slideValue, setSlideValue] = useState<number>(0)
  const changeSlideValue = (value: string | number) => {
    console.log('🚀 ~ changeSlideValue ~ value:', value)
    if (value == 'MAX' || value == 100) {
      setSlideValue(100)
      setInputValue(balanceInfo?.balanceFormat)
    } else {
      setSlideValue(Number((value + '').split('%')[0]))
      setInputValue(d(balanceInfo?.balanceFormat).mul(value).div(100).toString())
    }
  }
  return (
    <VStack gap="12px" width="100%" justifyContent="space-between">
      <Block h="42px" borderRadius="12px" lineHeight="42px" p="0 8px">
        <HStack w="100%" justify="space-between">
          <Text>Debt</Text>
          <HStack>
            <Text color="text_caption"> 100,000.99 USDC </Text>
            <Text color="primary_gray"> $100,000.99 </Text>
          </HStack>
        </HStack>
      </Block>
      <PositionSlider
        sliderBg="bg_secondary"
        percentage={slideValue}
        onChange={(value: string | number) => changeSlideValue(value)}
        textFontSize="20px"
        sliderTrackHeight="8px"
      />
      <TradeInput
        wrapStyle={{ h: 'unset' }}
        placeholder="0.0"
        value={inputValue}
        amountValue={amountValue}
        onChange={handleInputChange}
        token={currentToken}
        balance={balanceInfo?.balanceFormat || ''}
        inputStyle={{ width: '100%' }}
        dropSelectTokenList={dropSelectTokenList}
        changeCurrentToken={value => {
          changeCurrentToken(value)
        }}
        half={false}
        max={false}
      />
      <Button w="100%" h="48px" fontSize="18px" fontWeight="500" isDisabled={!inputValue}>
        Repay Debt
      </Button>
      <VStack w="100%" gap="16px" align="flex-start">
        <HStack w="100%" justify="space-between">
          <Text color="primary_gray">Debt</Text>
          <Text color="text_caption"> 100,000.99 USDC </Text>
        </HStack>
        <Leverage leverageValue="2.0x →2.1x" />
        <LiquidationPrice />
      </VStack>
    </VStack>
  )
}
