import useLeverageStore from '@/store/leverage'
import { Icon } from '@cetus/ui-kit'
import { textEllipses } from '@cetus/utils'
import { HStack, Text, VStack } from '@chakra-ui/react'
import { useState } from 'react'

function NetValue() {
  const [isShowNetValueDrop, setIsShowNetValueDrop] = useState(false)
  const { currentLeveragePool } = useLeverageStore()
  return (
    <>
      <HStack cursor="pointer" w="100%" justify="space-between">
        <Text color="primary_gray">Net Value</Text>
        <HStack gap="4px" onClick={() => setIsShowNetValueDrop(!isShowNetValueDrop)}>
          <Text color="text_caption">$0 → $3</Text>
          <Icon
            fontSize="12px"
            xlinkHref="#icon-icon_arrow"
            transition="transform 0.5s"
            transform={isShowNetValueDrop ? 'rotate(180deg)' : 'rotate(0deg)'}
          />
        </HStack>
      </HStack>
      {isShowNetValueDrop && (
        <VStack w="100%" p="12px" bg="card_bg" borderRadius="8px" gap="12px">
          <HStack w="100%" justify="space-between">
            <Text color="primary_gray">Collateral</Text>
            <Text color="text_caption">0 → 2 {textEllipses(currentLeveragePool?.displayTokenA?.symbol, 10)} ($6)</Text>
          </HStack>
          <HStack w="100%" justify="space-between">
            <Text color="primary_gray">Debt</Text>
            <Text color="text_caption">0 → 3 {textEllipses(currentLeveragePool?.displayTokenB?.symbol, 10)} ($3)</Text>
          </HStack>
        </VStack>
      )}
    </>
  )
}

export default NetValue
