import useLeverageStore from '@/store/leverage'
import { SelectTab, TradeInput } from '@cetus/design'
import useTokenPrice from '@cetus/hooks/src/useTokenPrice'
import { Token } from '@cetus/types'
import { Button, VStack } from '@chakra-ui/react'
import { useCallback, useState } from 'react'
import FlashBorrowFee from '../common/FlashBorrowFee'
import Leverage from '../common/Leverage'
import LiquidationPrice from '../common/LiquidationPrice'
import NetAPR from '../common/NetAPR'
import NetValue from '../common/NetValue'
import OpenFee from '../common/OpenFee'
import PriceDifference from '../common/PriceDifference'

const tabList = [
  {
    label: 'Deposit'
  },
  {
    label: 'Withdraw'
  }
]
export default function ManageSizeCon({
  currentToken,
  balanceInfo,
  dropSelectTokenList,
  changeCurrentToken
}: {
  currentToken: Token
  balanceInfo: any
  dropSelectTokenList: Token[]
  changeCurrentToken: (token: Token) => void
}) {
  const { currentLeveragePool } = useLeverageStore()
  const isLong = true
  const [currentTab, setCurrentTab] = useState('Deposit')
  const [inputValue, setInputValue] = useState<string>('')
  const { getTokenAmountValue } = useTokenPrice()
  const amountValue = getTokenAmountValue(currentToken?.coin_type, inputValue)
  const handleInputChange = useCallback((value: string) => {
    setInputValue(value)
  }, [])

  return (
    <VStack gap="12px" width="100%" justifyContent="space-between">
      <SelectTab
        type="outlineTab"
        wrapStyle={{
          w: '100%',
          h: '42px',
          bg: 'swap_bg_secondary',
          padding: '4px'
        }}
        itemStyle={{
          w: `50%`,
          fontSize: '14px',
          borderRadius: '8px'
        }}
        tabList={tabList}
        currentTab={currentTab}
        handleChangeTab={item => {
          setCurrentTab(item.label)
        }}
      />
      <TradeInput
        wrapStyle={{ h: 'unset' }}
        placeholder="0.0"
        value={inputValue}
        amountValue={amountValue}
        onChange={handleInputChange}
        token={currentToken}
        balance={currentTab === 'Deposit' ? balanceInfo?.balanceFormat || '' : ''}
        balanceLabel={currentTab === 'Deposit' ? '' : 'Available'}
        inputStyle={{ width: '100%' }}
        dropSelectTokenList={dropSelectTokenList}
        changeCurrentToken={value => {
          changeCurrentToken(value)
        }}
      />
      <Button w="100%" h="48px" fontSize="18px" fontWeight="500" isDisabled={!inputValue}>
        {currentTab}
      </Button>
      <VStack w="100%" gap="16px" align="flex-start">
        <NetAPR />
        <Leverage leverageValue="2.0x →2.0x" />
        <PriceDifference swapInToken={currentToken} outputToken={isLong ? currentLeveragePool?.displayTokenA : currentLeveragePool?.displayTokenB} />
        <NetValue />
        <LiquidationPrice />
        <FlashBorrowFee />
        {currentTab === 'Deposit' && <OpenFee />}
      </VStack>
    </VStack>
  )
}
