import { Block, TableSortTh } from '@cetus/design'
import { useAccountStore } from '@cetus/stores'
import { NoData } from '@cetus/ui-kit'
import { Box, HStack, Text, VStack } from '@chakra-ui/react'
import { useState } from 'react'
import PositionItem from './PositionItem'

export const tdWidth = ['30%', '15%', '15%', '15%', '15%', '10%']
type sortRule = 'desc' | 'asc'
export type type = {
  label: 'Size'
  value: 'size'
}
function PositionBlock() {
  const posList = [{}, {}]
  const { currentAccount, onWalletModal } = useAccountStore()
  const [isOpenList, setIsOpenList] = useState<number[]>([])
  const handleOpenItem = (index: number) => {
    setIsOpenList(prev => {
      if (prev.includes(index)) {
        return prev.filter(i => i !== index) // 移除已存在的index
      } else {
        return [...prev, index] // 添加新的index
      }
    })
  }

  const [sortRule, setSortRule] = useState<sortRule>('desc')
  const [sortBy, setSortBy] = useState<type>({ label: 'Size', value: 'size' })
  const clickSort = (item: type) => {
    if (item?.value == sortBy?.value) {
      const rule = sortRule == 'desc' ? 'asc' : 'desc'
      setSortRule(rule)
    } else {
      setSortRule('desc')
      setSortBy(item)
    }
  }
  const sortByList = [{ label: 'Size', value: 'size' }]
  const sortByObject = sortByList.reduce((obj: any, item) => {
    obj[item.value] = item
    return obj
  }, {})
  return (
    <Block position="relative" borderRadius="16px 12px 16px 16px" p="0px" maxH="590px" overflow="scroll">
      <HStack w="100%" position="sticky" top="0" bg="bg_secondary" p="16px" zIndex="99999">
        <Text color="primary_gray" w={tdWidth[0]}>
          Positions
        </Text>
        <Box w={tdWidth[1]}>
          <TableSortTh
            labelFontSize="13px"
            labelInfo={sortByObject['size']}
            sortRule={sortRule}
            sortBy={sortBy}
            clickSort={(value: type) => clickSort(value)}
          />
        </Box>
        <Text color="primary_gray" textAlign="right" w={tdWidth[2]}>
          PnL
        </Text>
        <Text color="primary_gray" textAlign="right" w={tdWidth[3]}>
          Entry Price
        </Text>
        <Text color="primary_gray" textAlign="right" w={tdWidth[4]}>
          Liq. Price
        </Text>
      </HStack>
      <VStack w="100%" align="flex-start" p="4px 12px 16px 16px" gap="16px">
        {!currentAccount?.address ? (
          <NoData type="nowallet" noBorder bg="none" onboard={() => onWalletModal(true)} />
        ) : posList?.length == 0 ? (
          <NoData type="nodata" text="No orders" noBorder bg="none" />
        ) : (
          posList?.map((item: any, index: number) => {
            const isOpen = isOpenList?.includes(index)
            return <PositionItem key={index} isOpen={isOpen} handleOpenItem={() => handleOpenItem(index)} />
          })
        )}
      </VStack>
    </Block>
  )
}

export default PositionBlock
