import useLeverageStore from '@/store/leverage'
import { Block } from '@cetus/design'
import { VStack } from '@chakra-ui/react'
import FlashBorrowFee from './common/FlashBorrowFee'
import LiquidationPrice from './common/LiquidationPrice'
import NetBorrowAPY from './common/NetBorrowAPY'
import NetValue from './common/NetValue'
import OpenFee from './common/OpenFee'
import PriceDifference from './common/PriceDifference'

function TradingShowData({ isLong }: { isLong?: boolean }) {
  const { currentLeveragePool, depositToken } = useLeverageStore()
  return (
    <Block borderRadius="16px" pt="48px" mt="-40px">
      <VStack w="100%" align="flex-start" gap="16px">
        <NetBorrowAPY />
        <LiquidationPrice />
        <NetValue />
        <PriceDifference swapInToken={depositToken} outputToken={isLong ? currentLeveragePool?.displayTokenA : currentLeveragePool?.displayTokenB} />
        <FlashBorrowFee />
        <OpenFee />
      </VStack>
    </Block>
  )
}

export default TradingShowData
