import { sliderStep } from '@/hooks/leverage/useLeverageTrading'
import useLeverageStore from '@/store/leverage'
import { Button, VStack } from '@chakra-ui/react'
import { useState } from 'react'
import FlashBorrowFee from '../common/FlashBorrowFee'
import Leverage from '../common/Leverage'
import LeverageSlider from '../common/LeverageSlider'
import LiquidationPrice from '../common/LiquidationPrice'
import NetAPR from '../common/NetAPR'
import NetValue from '../common/NetValue'
import PriceDifference from '../common/PriceDifference'

export default function ManageLeverageCon() {
  const { currentLeveragePool } = useLeverageStore()
  const [leverageValue, setLeverageValue] = useState(1.1)
  const changeLeverageValue = (value: number) => {
    setLeverageValue(value)
  }
  const isLong = true
  return (
    <VStack gap="12px" width="100%" justifyContent="space-between">
      <LeverageSlider leverageValue={leverageValue} sliderStep={sliderStep} changeLeverageValue={changeLeverageValue} />
      <Button w="100%" h="48px" fontSize="18px" fontWeight="500">
        Adjust Leverage
      </Button>
      <VStack w="100%" gap="16px" align="flex-start">
        <NetAPR />
        <Leverage leverageValue="2.0x →2.1x" />
        <PriceDifference
          swapInToken={isLong ? currentLeveragePool?.displayTokenB : currentLeveragePool?.displayTokenA}
          outputToken={isLong ? currentLeveragePool?.displayTokenA : currentLeveragePool?.displayTokenB}
        />
        <NetValue />
        <LiquidationPrice />
        <FlashBorrowFee />
      </VStack>
    </VStack>
  )
}
